import fs from 'node:fs'
import path from 'node:path'
import crypto from 'node:crypto'

const migrations = [
  '20261010150000_atomic_training_session_coach_save.sql',
  '20261010160000_atomic_calendar_event_coach_save.sql',
  '20261010170000_admin_billing_controls.sql',
  '20261011010000_marketplace_media_contract.sql',
  '20261011020000_message_reactions.sql',
  '20261011030000_message_attachment_contract.sql',
  '20261011040000_coach_saved_athletes_parity.sql',
  '20261011050000_repair_org_coach_assignment_eligibility.sql',
  '20261011060000_unify_org_notification_preferences.sql',
  '20261011070000_add_league_weekly_digest_preference.sql',
  '20261011080000_edge_function_security_controls.sql',
  '20261011090000_paperwork_lifecycle_and_audit.sql',
  '20261011100000_storage_and_verification_contracts.sql',
  '20261011110000_coach_waiver_storage_bucket_contract.sql',
  '20261012010000_profile_scope_purchased_training.sql',
  '20261012020000_league_document_signature_parity.sql',
  '20261012030000_league_document_file_metadata.sql',
  '20261012040000_league_management_action_parity.sql',
]

const root = process.cwd()
const migrationDirectory = path.join(root, 'supabase', 'migrations')
const output = process.argv[2]
  ? path.resolve(process.argv[2])
  : path.join(root, 'supabase', 'deployment', 'parity-release.sql')

const parts = migrations.map((name) => {
  const sourcePath = path.join(migrationDirectory, name)
  if (!fs.existsSync(sourcePath)) throw new Error(`Missing migration: ${name}`)
  const sql = fs.readFileSync(sourcePath, 'utf8').trim()
  if (!sql) throw new Error(`Empty migration: ${name}`)
  return `-- BEGIN ${name}\n${sql}\n-- END ${name}`
})

const bundle = [
  '-- Generated by scripts/build-parity-deployment-bundle.mjs.',
  '-- Apply once, in one transaction, after reviewing the linked-project deployment gate.',
  'begin;',
  ...parts,
  "notify pgrst, 'reload schema';",
  'commit;',
  '',
].join('\n\n')

fs.mkdirSync(path.dirname(output), { recursive: true })
fs.writeFileSync(output, bundle)
const digest = crypto.createHash('sha256').update(bundle).digest('hex')
console.log(`${output}\nsha256 ${digest}\n${migrations.length} migrations`)
